mapper.select:

inner join (
    select A.id from articles A
    inner join article_bookmarks AB on AB.article_id = A.id
    where AB.user_id = #{currentUser.id}
    order by A.created_at desc, A.id
    limit #{page.offset}, #{page.limit}
) B on B.id = A.id
order by A.created_at desc, A.id

select count(1) from articles A
inner join article_bookmarks AB on AB.article_id = A.id
where AB.user_id = #{currentUser.id}
